"""Tide appearance roles. Component geometry lives in the unchanged shared stylesheets."""
ROLE_KEYS = {'surface-canvas': 'base', 'surface-card': 'panel', 'surface-raised': 'raised', 'surface-field': 'field', 'text-primary': 'primary', 'text-secondary': 'secondary', 'text-label': 'label', 'text-tertiary': 'tertiary', 'accent': 'accent', 'on-accent': 'onAccent', 'border-subtle': 'subtle', 'border-strong': 'strong', 'border-control': 'control', 'selection-surface': 'selected', 'selection-border': 'selectedLine', 'status-success': 'success', 'status-success-surface': 'successBg', 'status-success-border': 'successLine', 'status-warning': 'warning', 'status-warning-surface': 'warningBg', 'status-warning-border': 'warningLine', 'status-danger': 'danger', 'status-danger-surface': 'dangerBg', 'status-danger-border': 'dangerLine', 'photo-accent': 'heroAccent'}
COMMON = '\nhtml { background:var(--color-surface-canvas); color-scheme:var(--theme-scheme); scroll-behavior:auto !important; }\nbody[data-study="01"] { --surface-base:var(--color-surface-canvas); --surface-panel:var(--color-surface-card); --text-primary:var(--color-text-primary); --text-secondary:var(--color-text-secondary); --text-label:var(--color-text-label); --text-tertiary:var(--color-text-tertiary); --accent:var(--color-accent); --line-subtle:var(--color-border-subtle); --line-strong:var(--color-border-strong); --action-radius:var(--corner-action); --texture-opacity:var(--texture-strength); }\n:root { --surface-raised:var(--color-surface-raised); --surface-field:var(--color-surface-field); --control-border:var(--color-border-control); --radius-control:var(--corner-action); --radius-panel:var(--corner-panel); --success:var(--color-status-success); --success-bg:var(--color-status-success-surface); --warning:var(--color-status-warning); --warning-bg:var(--color-status-warning-surface); --danger:var(--color-status-danger); --danger-bg:var(--color-status-danger-surface); --selected-bg:var(--color-selection-surface); --selected-line:var(--color-selection-border); --kit-switch-radius:var(--corner-field); }\n.btn:not(.secondary):not(.quiet):not(:disabled) { color:var(--color-on-accent); }\n.btn:not(.secondary):not(.quiet):not(:disabled) .icon { filter:var(--icon-filter-action); }\n.btn.secondary .icon,.icon { filter:var(--icon-filter-default); }\n.icon-btn.selected { background:var(--color-selection-surface); border-color:var(--color-selection-border); }\n.chip.selected,.chip:has(input:checked) { background:var(--color-selection-surface); border-color:var(--color-selection-border); }\n.field input:not([type=checkbox]):not([type=radio]):not([type=file]),.field select,.field textarea { border-radius:var(--corner-field); }\n.chip { border-radius:var(--corner-chip); }\n.icon-btn,.screen-study figcaption > a,.round-control { border-radius:var(--corner-icon); }\n.badge { border-radius:var(--corner-badge); }\n.badge.success { border-color:var(--color-status-success-border); }\n.badge.warning { border-color:var(--color-status-warning-border); }\n.badge.danger { border-color:var(--color-status-danger-border); }\n.notice,.upload-field,.swatch,input::file-selector-button { border-radius:var(--corner-field); }\n.toast-sample,.organizer { border-radius:var(--corner-action); }\n.doc-panel,.hero-card { border-radius:var(--corner-panel); }\n.skip-link { color:var(--color-on-accent); }\n/* The photograph is a distinct dark surface in every skin. Its crop, scrim and geometry stay fixed. */\n.event-hero { --surface-base:#111517; --text-primary:#f0f1ed; --text-secondary:#b8bfc6; --text-label:#aab3ba; --text-tertiary:#939da6; --accent:var(--color-photo-accent); color:var(--text-primary); }\n.event-hero .icon { filter:none; }\n.event-hero .primary-action { color:#211a27; }\n.event-hero .primary-action .icon { filter:brightness(0); }\n@media(prefers-contrast:more) { body[data-study="01"] { --texture-opacity:0; } }\n\n/* Callouts use a uniform neutral outline. Preserve the original text alignment. */\n.notice,.notice.error,.notice.success { border:1px solid var(--line-strong); padding-inline-start:calc(var(--space-4) + 2px); }\n'

def role_colors(palette):
 return {role:palette[key] for role,key in ROLE_KEYS.items()}

def stylesheet(palette):
 values=['--color-'+name+':'+value for name,value in role_colors(palette).items()]
 values+=['--corner-'+name+':'+str(value)+'px' for name,value in zip(['field','action','panel','chip','badge','icon'],palette['radii'])]
 values+=['--theme-scheme:'+palette['scheme'],'--texture-strength:'+str(palette['texture'])]
 values+=['--icon-filter-default:'+('brightness(.18)' if palette['scheme']=='light' else 'none'),'--icon-filter-action:'+('brightness(0) invert(1)' if palette['scheme']=='light' else 'brightness(0)')]
 return '/* Semantic palette roles. Square geometry is shared by every Tide study. */\n:root {'+';'.join(values)+';}\n'+COMMON
